/* @autogenerated */
import { Directive, TemplateRef, viewChild } from '@angular/core';
import { DocumentDefinition } from '@shared/toolkit/entity-document/document.model';
import { BaseAction } from './base-action';

/**
 * Acción que genera un documento (Word / PDF) de un elemento desde una plantilla Markdown. Es contextual (un
 * elemento) y su plantilla `#documentTemplate` muestra
 * `<entity-document [definition]="definition" [item]="selection()[0]" (closed)="close()" />`.
 *
 * Textos: `<scope>.action.<name>.*` con fallback a `common.action.document.*`. Visible si el ACL permite `retrieve`.
 */
@Directive()
export abstract class BaseDocumentAction<T> extends BaseAction<T> {
  override readonly contextual = true;
  override readonly multiple = false;
  override readonly render = viewChild<TemplateRef<any>>('documentTemplate');

  abstract readonly definition: DocumentDefinition<T>;

  run(): void {
    // La pantalla rellena la plantilla y ofrece la descarga
  }

  close(): void {
    this.container()?.close();
  }

  protected override get commonTextKey(): string {
    return 'document';
  }

  protected override get permission(): string {
    return 'retrieve';
  }
}
